questions.solution:
def tiled_matmul(A, B, tile):
    """C = A * B, accumulated over K one tile of width `tile` at a time; slots past K count as 0.0."""
    M, K, N = len(A), len(B), len(B[0])
    C = [[0.0] * N for _ in range(M)]
    for t in range((K + tile - 1) // tile):
        for i in range(M):
            for j in range(N):
                for k in range(tile):
                    kk = t * tile + k
                    a = A[i][kk] if kk < K else 0.0
                    b = B[kk][j] if kk < K else 0.0
                    C[i][j] += a * b
    return C
